use super::*;
use serde::{Deserialize,Serialize};
#[derive(Default,Serialize,Deserialize)] #[serde(default)] pub(super) struct Prefs {pub scene:bool,pub inspector:bool,pub bottom:bool,pub recent:Vec<PathBuf>,pub camera:bool,pub bounds:std::collections::BTreeMap<String,[f32;4]>}
#[derive(Default)] pub(super) struct Workspace {pub prefs:Prefs,pub manager:bool,loaded:bool,folder:String,kind:usize}
fn path()->PathBuf{std::env::var_os("APPDATA").or_else(||std::env::var_os("HOME")).map(PathBuf::from).unwrap_or_else(std::env::temp_dir).join("ForgeEngine").join("workspace35.json")}
fn save(e:&mut Editor){let p=path();let result=(||->Result<(),String>{std::fs::create_dir_all(p.parent().unwrap()).map_err(|x|x.to_string())?;std::fs::write(p,serde_json::to_vec_pretty(&e.workspace.prefs).map_err(|x|x.to_string())?).map_err(|x|x.to_string())})();if let Err(err)=result{e.status=err;}}
pub(super) fn init(e:&mut Editor){if e.workspace.loaded{return;}e.workspace.loaded=true;if let Ok(b)=std::fs::read(path()){if let Ok(p)=serde_json::from_slice(&b){e.workspace.prefs=p;}}e.workspace.manager=e.path.is_none();}
pub(super) fn floating_window(ctx:&egui::Context,title:&str,id:&str,bounds:Option<[f32;4]>,panel:impl FnOnce(&mut egui::Ui))->Option<[f32;4]>{let mut w=egui::Window::new(title).id(egui::Id::new(id)).default_width(320.).resizable(true);if let Some(b)=bounds{w=w.default_pos(egui::pos2(b[0],b[1])).default_size(egui::vec2(b[2].max(120.),b[3].max(80.)));}w.show(ctx,panel).map(|r|{let r=r.response.rect;[r.min.x,r.min.y,r.width(),r.height()]})}
pub(super) fn menu(ui:&mut egui::Ui,e:&mut Editor){let uk=e.uk;ui.label(tr(uk,"Від'єднані панелі","Floating panels"));ui.checkbox(&mut e.workspace.prefs.scene,tr(uk,"Сцена","Scene"));ui.checkbox(&mut e.workspace.prefs.inspector,tr(uk,"Інспектор","Inspector"));ui.checkbox(&mut e.workspace.prefs.bottom,tr(uk,"Інструменти","Tools"));ui.checkbox(&mut e.workspace.prefs.camera,tr(uk,"Камера","Camera preview"));if ui.button(tr(uk,"Зберегти розташування","Save layout")).clicked(){save(e);}if ui.button(tr(uk,"Закріпити всі","Dock all")).clicked(){e.workspace.prefs.scene=false;e.workspace.prefs.inspector=false;e.workspace.prefs.bottom=false;save(e);}}
pub(super) fn manager(ctx:&egui::Context,e:&mut Editor){if let Some(p)=e.path.clone(){if !e.workspace.prefs.recent.contains(&p){e.workspace.prefs.recent.insert(0,p);e.workspace.prefs.recent.truncate(12);save(e);}}if !e.workspace.manager{return;}let uk=e.uk;let mut open=true;egui::Window::new(tr(uk,"Менеджер проєктів","Project manager")).id(egui::Id::new("project_manager35")).default_width(440.).open(&mut open).show(ctx,|ui|{ui.heading("FORGE ENGINE");ui.label(tr(uk,"Шаблони проєктів","Project templates"));for (name,kind) in [(tr(uk,"Порожній 2D","Empty 2D"),0),(tr(uk,"Платформер","Platformer"),1),(tr(uk,"Ізометрія","Isometric"),2)]{if ui.button(name).clicked()&&e.confirm_discard(){let mut p=Project::default();p.name=name.into();if kind==0{p.objects.clear();}if kind==1{for o in &mut p.objects{o.body=if o.player{Body::Dynamic}else{Body::Static};}}if kind==2{p.isometric=true;}replace(e,p,None);e.workspace.manager=false;}}if ui.button(tr(uk,"Відкрити файл","Open file")).clicked(){e.open();if e.path.is_some(){e.workspace.manager=false;}}ui.separator();ui.label(tr(uk,"Недавні проєкти","Recent projects"));for p in e.workspace.prefs.recent.clone(){if ui.button(p.display().to_string()).clicked()&&e.confirm_discard(){match Project::load(&p){Ok(project)=>{replace(e,project,Some(p));e.workspace.manager=false;},Err(err)=>e.status=err}}}});if !open{e.workspace.manager=false;}}
fn replace(e:&mut Editor,p:Project,path:Option<PathBuf>){e.saved=p.clone();e.project=p;e.path=path;e.selected=None;e.pro.multi.clear();e.pro.last_scan=None;e.pro.last_backup=None;e.undo.clear();e.redo.clear();e.textures.clear();e.stamps.clear();e.play=None;e.preview=0.;e.preview_play=false;}
pub(super) fn inspector(ui:&mut egui::Ui,o:&mut Object,uk:bool){ui.horizontal_wrapped(|ui|{let r=ui.label(tr(uk,"Трансформація","Transform"));r.context_menu(|ui|{if ui.button(tr(uk,"Скинути позицію","Reset position")).clicked(){o.position=[0.,0.];}if ui.button(tr(uk,"Скинути кут","Reset rotation")).clicked(){o.rotation=0.;}if ui.button(tr(uk,"Скинути розмір","Reset size")).clicked(){o.size=[64.,64.];}});ui.menu_button(tr(uk,"+ Компонент","+ Component"),|ui|{if ui.button("Camera2D").clicked(){o.camera=true;}if ui.button("RigidBody2D").clicked(){o.body=Body::Dynamic;}if ui.button("Trigger2D").clicked(){o.body=Body::Trigger;}if ui.button("Lua").clicked()&&o.script.is_empty(){o.script="function update(dt)\nend".into();}});});}
pub(super) fn add_asset(e:&mut Editor,rel:&str,pos:[f32;2]){if !e.pro.assets.iter().any(|r|r==rel){return;}if let Some(root)=e.path.as_ref().and_then(|p|p.parent()){match image::open(root.join(rel)){Ok(img)=>{let mut o=Object::new(rel.rsplit('/').next().unwrap_or(rel),pos,[img.width() as f32,img.height() as f32],[255;4]);o.sprite=Some(rel.into());e.selected=Some(o.id);e.pro.multi.clear();e.project.objects.push(o);},Err(err)=>e.status=err.to_string()}}}
pub(super) fn assets(ui:&mut egui::Ui,e:&mut Editor,ctx:&egui::Context){let uk=e.uk;super::max::assets(ui,e);super::master::asset_tools(ui,e);ui.horizontal(|ui|{if ui.button(tr(uk,"Імпорт","Import")).clicked(){e.import();}ui.add(egui::TextEdit::singleline(&mut e.pro.filter).hint_text(tr(uk,"Пошук","Search")));egui::ComboBox::from_id_salt("asset_kind35").selected_text(["All","PNG","JPEG"][e.workspace.kind]).show_ui(ui,|ui|{for (i,k) in ["All","PNG","JPEG"].iter().enumerate(){ui.selectable_value(&mut e.workspace.kind,i,*k);}});});let mut folders=std::collections::BTreeSet::new();for r in &e.pro.assets{let mut parts=r.split('/').collect::<Vec<_>>();parts.pop();while !parts.is_empty(){folders.insert(parts.join("/"));parts.pop();}}ui.horizontal_wrapped(|ui|{if ui.selectable_label(e.workspace.folder.is_empty(),tr(uk,"Усі папки","All folders")).clicked(){e.workspace.folder.clear();}for f in folders{if ui.selectable_label(e.workspace.folder==f,&f).clicked(){e.workspace.folder=f;}}});let mut add=None;egui::ScrollArea::vertical().id_salt("asset35").show(ui,|ui|{ui.horizontal_wrapped(|ui|{for rel in e.pro.assets.clone(){let lower=rel.to_lowercase();if !lower.contains(&e.pro.filter.to_lowercase())||(!e.workspace.folder.is_empty()&&!rel.starts_with(&format!("{}/",e.workspace.folder)))||(e.workspace.kind==1&&!lower.ends_with(".png"))||(e.workspace.kind==2&&!(lower.ends_with(".jpg")||lower.ends_with(".jpeg"))){continue;}let key=format!("thumb:{rel}");if !e.textures.contains_key(&key){if let Some(root)=e.path.as_ref().and_then(|p|p.parent()){if let Ok(img)=image::open(root.join(&rel)){let rgba=img.thumbnail(80,80).to_rgba8();e.textures.insert(key.clone(),ctx.load_texture(key.clone(),egui::ColorImage::from_rgba_unmultiplied([rgba.width() as usize,rgba.height() as usize],rgba.as_raw()),egui::TextureOptions::NEAREST));if let Ok(t)=std::fs::metadata(root.join(&rel)).and_then(|m|m.modified()){e.stamps.insert(rel.clone(),t);}}}}ui.vertical(|ui|{if let Some(tex)=e.textures.get(&key){let r=ui.add(egui::Image::new((tex.id(),egui::vec2(64.,64.))).sense(egui::Sense::click_and_drag()));r.dnd_set_drag_payload(rel.clone());if r.double_clicked(){add=Some(rel.clone());}}let r=ui.add(egui::Label::new(rel.rsplit('/').next().unwrap_or(&rel)).sense(egui::Sense::click_and_drag()));r.dnd_set_drag_payload(rel.clone());if r.clicked(){e.pro.asset_pick=Some(rel.clone());e.master.asset_target=rel.clone();}if r.double_clicked(){add=Some(rel.clone());}});}});});if let Some(rel)=add{add_asset(e,&rel,[0.,0.]);}}
pub(super) fn timeline(ui:&mut egui::Ui,o:&mut Object,time:&mut f32,uk:bool){let end=o.motion.keys.iter().map(|k|k.time).fold((o.animation.frames as f32/o.animation.fps.max(1.)).max(1.),f32::max);ui.horizontal(|ui|{if ui.button(tr(uk,"+ Ключ","+ Key")).clicked(){o.motion.keys.push(forge_engine::Key{time:*time,position:o.position,rotation:o.rotation,smooth:false,bezier:None});}ui.label(format!("{:.2} s",*time));});let (r,response)=ui.allocate_exact_size(egui::vec2(ui.available_width().max(80.),86.),egui::Sense::click_and_drag());let p=ui.painter_at(r);p.rect_filled(r,3.,egui::Color32::from_rgb(20,24,31));let left=r.left()+55.;let width=(r.right()-left).max(1.);let x=|t:f32|left+t/end*width;for (i,name) in ["X","Y","Angle"].iter().enumerate(){let y=r.top()+14.+i as f32*25.;p.text(egui::pos2(r.left()+5.,y),egui::Align2::LEFT_CENTER,*name,egui::FontId::monospace(11.),egui::Color32::GRAY);p.line_segment([egui::pos2(left,y),egui::pos2(r.right(),y)],egui::Stroke::new(1.,egui::Color32::DARK_GRAY));for k in &o.motion.keys{let c=egui::pos2(x(k.time),y);p.add(egui::Shape::convex_polygon(vec![c+egui::vec2(0.,-5.),c+egui::vec2(5.,0.),c+egui::vec2(0.,5.),c+egui::vec2(-5.,0.)],egui::Color32::LIGHT_BLUE,egui::Stroke::NONE));}}if response.clicked()||response.dragged(){if let Some(pos)=response.interact_pointer_pos(){*time=((pos.x-left)/width*end).clamp(0.,end);}}let cursor=x(*time);p.line_segment([egui::pos2(cursor,r.top()),egui::pos2(cursor,r.bottom())],egui::Stroke::new(2.,egui::Color32::YELLOW));}

pub(super) fn camera_window(ctx:&egui::Context,e:&mut Editor,texture:egui::TextureId){if !e.workspace.prefs.camera{return;}let uk=e.uk;let mut open=true;egui::Window::new(tr(uk,"Перегляд камери","Camera preview")).id(egui::Id::new("camera35")).open(&mut open).default_width(480.).show(ctx,|ui|{if e.project.objects.iter().any(|o|o.camera){let w=ui.available_width().max(80.);ui.image((texture,egui::vec2(w,w*9./16.)));ui.label(format!("{} × {} · Bevy",e.master.settings.resolution[0],e.master.settings.resolution[1]));}else{ui.label(tr(uk,"Додайте компонент Camera2D до об'єкта.","Add a Camera2D component to an object."));}});if !open{e.workspace.prefs.camera=false;}}
